export const NOTE_SLOTS=[{x:.325,y:.13,tilt:.09},{x:.335,y:.02,tilt:-.05},{x:.325,y:-.09,tilt:.12},{x:-.325,y:.13,tilt:-.08},{x:-.335,y:.02,tilt:.06},{x:-.325,y:-.09,tilt:-.11}],NOTE_SIZE=.085,ATLAS={cols:3,rows:2},NOTE_COLORS={overdue:"#f6a9bb",today:"#fbe38e",more:"#a9d8f2"};export function stickyNotes(t,o=NOTE_SLOTS.length){const e=[...t.overdue.map(n=>({kind:"task",task:n,overdue:!0})),...t.today.map(n=>({kind:"task",task:n,overdue:!1}))];if(e.length<=o)return e;const r=e.slice(0,o-1);return r.push({kind:"more",count:e.length-r.length}),r}export function notesKey(t){return t.map(o=>o.kind==="more"?`+${o.count}`:`${o.task.id}:${o.task.text}:${o.overdue}`).join("|")}export function noteWords(t){return t.kind==="more"?{text:`${t.count} more`,small:"on the Today list"}:{text:t.task.text,small:t.overdue?"Overdue":"Today"}}export function noteColor(t){return t.kind==="more"?NOTE_COLORS.more:t.overdue?NOTE_COLORS.overdue:NOTE_COLORS.today}export function quadCorners(t,o=NOTE_SIZE){const e=o/2,r=Math.cos(t.tilt),n=Math.sin(t.tilt);return[[-e,-e],[e,-e],[e,e],[-e,e]].map(([s,c])=>[t.x+s*r-c*n,t.y+s*n+c*r])}export function cellUvs(t,o=ATLAS){const e=t%o.cols,r=Math.floor(t/o.cols),n=e/o.cols,s=(e+1)/o.cols,c=1-r/o.rows,u=1-(r+1)/o.rows;return[[n,u],[s,u],[s,c],[n,c]]}
